def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves."""
    changes = set()
    _compare(before, after, "", changes)
    return sorted(changes)


def _compare(before, after, prefix, changes):
    all_keys = set(before) | set(after)
    for key in all_keys:
        path = f"{prefix}.{key}" if prefix else key
        if key not in before:
            changes.add(path)
        elif key not in after:
            changes.add(path)
        else:
            b_val = before[key]
            a_val = after[key]
            if isinstance(b_val, dict) and isinstance(a_val, dict):
                _compare(b_val, a_val, path, changes)
            else:
                if b_val != a_val:
                    changes.add(path)
