def normalize(path):
    if not path.startswith('/'):
        raise ValueError(f"Path must be absolute: {path!r}")

    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    if not stack:
        return '/'
    return '/' + '/'.join(stack)
