def redact(value, sensitive):
    """Recursively copy a JSON-like structure, redacting sensitive keys.

    Args:
        value: A JSON-like value (dict, list, or scalar).
        sensitive: An iterable of strings identifying keys to redact
                   (matched case-insensitively and exactly).

    Returns:
        A new structure with matching key values replaced by "[REDACTED]".
    """
    sensitive_lower = {s.lower() for s in sensitive}
    return _redact(value, sensitive_lower)


def _redact(value, sensitive_lower):
    if isinstance(value, dict):
        result = {}
        for key, val in value.items():
            if isinstance(key, str) and key.lower() in sensitive_lower:
                result[key] = "[REDACTED]"
            else:
                result[key] = _redact(val, sensitive_lower)
        return result
    elif isinstance(value, list):
        return [_redact(item, sensitive_lower) for item in value]
    else:
        return value
